#include "tensorrt_backend.hpp"
#include <opencv2/imgcodecs.hpp>
#include <iostream>
#include <numeric>
lesson21::BatchMetadata metadata(std::uint64_t batch,int n,const cv::Mat& image){lesson21::BatchMetadata m;m.batch_id=batch;for(int i=0;i<n;++i)m.frames.push_back({(size_t)batch,(std::uint64_t)i,(size_t)i,lesson21::Clock::now(),{1,0,0,image.cols,image.rows}});return m;}
void print(const lesson21::GpuBatchResult&r){double sum=std::accumulate(r.output.begin(),r.output.end(),0.0);std::cout<<"backend=tensorrt batch_id="<<r.metadata.batch_id<<" batch="<<r.metadata.frames.size()<<" output_elements="<<r.output.size()<<" checksum="<<sum<<" preprocess_ms="<<r.preprocess_ms<<" inference_ms="<<r.inference_ms<<" d2h_ms="<<r.d2h_ms<<'\n';}
int main(int argc,char**argv){if(argc<3){std::cerr<<"usage: integrated_tensorrt_gpu_smoke ENGINE IMAGE [BATCH] [--two-slots]\n";return 2;}try{int n=argc>3?std::stoi(argv[3]):1;if(n<1||n>4)throw std::invalid_argument("batch must be 1..4");cv::Mat image=cv::imread(argv[2]);if(image.empty())throw std::runtime_error("cannot read image");lesson21::TensorRtBackend backend(argv[1],2,{640,640});std::vector<cv::Mat> images(n,image);backend.submit(0,images,metadata(0,n,image));if(argc>4){backend.submit(1,images,metadata(1,n,image));print(backend.collect(1));}print(backend.collect(0));return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
